import React from 'react';

import ArrowRightShort from '@pohodnik/icons/svg/Arrows/ArrowRightShort';
import { Link } from 'react-router-dom';

import { getOneFundAsync } from '@apps/Finances/@services/funds.service';
import { IFundWithPayments } from '@apps/Finances/@types/funds.types';
import { editFundInModalAsync } from '@apps/Finances/components/FundEdit';
import HikingBadge from '@apps/Hiking/@components/HikingBadge';
import Page from '@components/Page';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { formatFinance } from '@helpers/formatHelper';
import { fullNameForUser } from '@helpers/user.helper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

interface IFundOnePageProps {
  id: number;
}

const FundOnePage: React.FC<IFundOnePageProps> = ({ id }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IFundWithPayments>();
  const [err, setErr] = React.useState<Error>();

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const d = await getOneFundAsync(id);
        setData(d);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  const handleEdit = () => {
    if (!data) return;
    editFundInModalAsync(data).then((up) => {
      setData((cur) => ({ ...(cur as IFundWithPayments), up }));
    });
  };

  if (!data) {
    return <PohAlert>No data</PohAlert>;
  }

  const s = data.payments.reduce(
    (acc, val) => {
      return {
        inc: acc.inc + (val.fundTo?.id === +id ? val.total : 0),
        exp: acc.exp + (val.fundFrom?.id === +id ? val.total : 0),
      };
    },
    { inc: 0, exp: 0 },
  );

  return (
    <Page title={data.name}>
      <Breadcrumb
        data={[
          { href: '/finances', text: 'Финансы' },
          { href: '/finances/funds', text: 'Фонды' },
          { href: `/finances/funds/${id}`, text: data.name, active: true },
        ]}
      />

      <PohContainer>
        <PageHeader title={data.name} subtitle={data.description}>
          <PohButton size={ButtonSize.Small} variant={ButtonVariant.Success} onClick={handleEdit}>
            Редактировать
          </PohButton>
        </PageHeader>

        <PohRow className="mb-3">
          <PohCol lg={1} md={2} sm={3} xs={4}>
            <h4 className="m-0">{formatFinance(s.inc - s.exp)}</h4>
            <small className="text-muted mt-n1 d-block">Баланс</small>
          </PohCol>
          <PohCol lg={1} md={2} sm={3} xs={4}>
            <h4 className="m-0 text-success">{formatFinance(s.inc)}</h4>
            <small className="text-muted mt-n1 d-block">Доходов</small>
          </PohCol>
          <PohCol lg={1} md={2} sm={3} xs={4}>
            <h4 className="m-0 text-danger">{formatFinance(s.exp)}</h4>
            <small className="text-muted mt-n1 d-block">Расходов</small>
          </PohCol>
        </PohRow>

        <PohRow>
          <PohList
            data={data.payments.map((p) => {
              return {
                key: p.id,
                children: (
                  <PohRow className="align-items-center">
                    <PohCol lg={1} md={2} sm={3} xs={4}>
                      <div style={{ lineHeight: 0.9 }} className="text-end">
                        <strong className="text-success">{formatFinance(p.total)}</strong>
                        <br />
                        <small className="text-muted">{p.date.toLocaleDateString()}</small>
                      </div>
                    </PohCol>
                    <PohCol
                      md={2}
                      sm={3}
                      xs={4}
                      className="d-flex justify-content-between align-items-center"
                    >
                      {p.userFrom && (
                        <div className="d-flex align-items-center">
                          <PohAva
                            src={p.userFrom?.photo}
                            alt={fullNameForUser(p.userFrom)}
                            colorize
                          />
                          <div className="ms-2" style={{ lineHeight: 0.9 }}>
                            {p.userFrom.name}
                            <br />
                            {p.userFrom.surname}
                          </div>
                        </div>
                      )}
                      {p.fundFrom && (
                        <div className="d-flex align-items-center">
                          <PohAva alt={p.fundFrom.name} colorize />
                          <div className="ms-2" style={{ lineHeight: 0.9 }}>
                            {p.fundFrom.name}
                          </div>
                        </div>
                      )}
                      <ArrowRightShort />
                    </PohCol>
                    <PohCol md={2} sm={3} xs={4}>
                      {p.userTo && (
                        <div className="d-flex align-items-center">
                          <PohAva src={p.userTo?.photo} alt={fullNameForUser(p.userTo)} colorize />
                          <div className="ms-2" style={{ lineHeight: 0.9 }}>
                            {p.userTo.name}
                            <br />
                            {p.userTo.surname}
                          </div>
                        </div>
                      )}
                      {p.fundTo && (
                        <div className="d-flex align-items-center">
                          <PohAva alt={p.fundTo.name} colorize />
                          <div className="ms-2" style={{ lineHeight: 0.9 }}>
                            {p.fundTo.name}
                          </div>
                        </div>
                      )}
                    </PohCol>
                    <PohCol md={2} sm={3} xs={4}>
                      <em>{p.comment}</em>
                    </PohCol>
                    <PohCol md={2} sm={3} xs={4}>
                      <Link to={`/hiking/${p.hiking.id}/finances`}>
                        <HikingBadge hiking={p.hiking} />
                      </Link>
                    </PohCol>
                  </PohRow>
                ),
              };
            })}
          />
        </PohRow>
      </PohContainer>
    </Page>
  );
};

export default FundOnePage;
